// Optional user-supplied assets. asset-manifest.json (generated by the Vite
// plugin in vite.config.js) lists the files found in public/models/* and
// public/audio; everything falls back silently to procedural content.

const EMPTY = { characters: [], animations: [], vehicles: [], furniture: [], audio: [] };
let manifest = null;

export async function loadAssetManifest() {
  if (manifest) return manifest;
  try {
    const r = await fetch('./asset-manifest.json', { cache: 'no-cache' });
    const type = r.headers.get('content-type') || '';
    manifest = r.ok && type.includes('json') ? { ...EMPTY, ...(await r.json()) } : EMPTY;
  } catch {
    manifest = EMPTY;
  }
  return manifest;
}

export const assetManifest = () => manifest || EMPTY;
